/* Attack statistics filter by shooter team; keeper statistics filter by defending team. */
function playerKeys(shots,events=[]){
 const keys=new Map();const add=(tid,n)=>keys.set(JSON.stringify([tid,n]),{team:tid,player:n});
 for(const t of db.teams.filter(t=>matchesTeam(t.id)&&selectedGames().some(g=>g.home===t.id||g.away===t.id)))for(const p of t.players)add(t.id,p.number);
 for(const e of [...shots,...events])add(e.team,e.player);
 return [...keys.values()].sort((a,b)=>teamName(a.team).localeCompare(teamName(b.team),'de')||Number(a.player)-Number(b.player)||a.player.localeCompare(b.player));
}
function eventSummary(events){return playerKeys([],events).map(p=>{const own=events.filter(e=>e.team===p.team&&e.player===p.player),losses=own.filter(e=>e.result==='Ballverlust').length,errors=own.filter(e=>e.result==='Technischer Fehler').length;return {...p,losses,errors,total:losses+errors}})}
function routesFor(shots){const groups=new Map();for(const shot of shots){if(!origins.includes(shot.origin)||!Number.isInteger(shot.zone)||shot.zone<0||shot.zone>8)continue;const key=JSON.stringify([shot.origin,shot.zone]),r=groups.get(key)||{origin:shot.origin,zone:shot.zone,count:0,goals:0};r.count++;if(shot.result==='Tor')r.goals++;groups.set(key,r)}return [...groups.values()].sort((a,b)=>b.count-a.count||origins.indexOf(a.origin)-origins.indexOf(b.origin)||a.zone-b.zone)}
function filterText(kind){const ids=filter[kind],all=kind==='teams'?db.teams:db.games;if(!ids.length)return kind==='teams'?'Alle Mannschaften':'Alle Spiele';if(ids.length===1){const item=all.find(x=>x.id===ids[0]);return kind==='teams'?teamName(ids[0]):item?`${item.date} · ${teamName(item.home)} – ${teamName(item.away)}`:'1 Spiel'}return ids.length+(kind==='teams'?' Mannschaften':' Spiele')}
analysisView=function(){
 const shots=filtered(),goals=shots.filter(s=>s.result==='Tor').length,known=shots.filter(s=>s.zone!=null),events=filteredEvents(),players=playerKeys(shots,events);
 return `<div class="topline"><div><div class="eyebrow">Muster erkennen</div><h1>Das Spiel hinter den Zahlen.</h1><p class="muted">Spieler antippen, um bevorzugte Wurfwege zu sehen.</p></div><button data-action="csv">↓ CSV exportieren</button></div><div class="analysis-filters"><button data-analysis-filter="teams"><small>Mannschaften · Mehrfachauswahl</small><span>${esc(filterText('teams'))}</span><b>⌄</b></button><button data-analysis-filter="games"><small>Spiele · Mehrfachauswahl</small><span>${esc(filterText('games'))}</span><b>⌄</b></button></div><div class="stats">${[[shots.length,'Erfasste Würfe'],[goals,'Tore'],[shots.length?Math.round(goals/shots.length*100)+' %':'–','Trefferquote'],[events.length,'Ereignisse ohne Wurf']].map(([v,n])=>`<div class="stat"><strong>${v}</strong><span>${n}</span></div>`).join('')}</div><div class="card"><div class="card-head"><div><h2>Spielervergleich</h2><p class="muted" style="margin-top:6px">Zeile antippen → Wurfbild der ausgewählten Spiele</p></div><span class="pill">${players.length} Spieler</span></div><div class="tablewrap"><table class="player-comparison"><thead><tr><th>Mannschaft</th><th>Spieler</th><th>Würfe</th><th>Tore</th><th>Quote</th><th></th></tr></thead><tbody>${players.map(p=>{const a=shots.filter(s=>s.team===p.team&&s.player===p.player),n=a.filter(s=>s.result==='Tor').length;return `<tr role="button" tabindex="0" data-heat-team="${esc(p.team)}" data-heat-player="${esc(p.player)}" aria-label="Wurfbild ${esc(teamName(p.team))} Nummer ${esc(p.player)} ${esc(playerName(p.team,p.player))}"><td>${esc(teamName(p.team))}</td><td><b>#${esc(p.player)} ${esc(playerName(p.team,p.player))}</b>${playerFlags(team(p.team)?.players.find(x=>x.number===p.player))}</td><td>${a.length}</td><td>${n}</td><td>${a.length?Math.round(n/a.length*100)+' %':'–'}</td><td class="heat-link">Wurfbild ↗</td></tr>`}).join('')||'<tr><td colspan="6">Keine Spieler für diese Auswahl.</td></tr>'}</tbody></table></div></div><div class="split"><div class="card"><div class="card-head"><h2>Wurfverteilung im Tor</h2><span class="pill">${known.length} zugeordnet</span></div><div class="goal">${zones.map((z,i)=>{const a=known.filter(s=>s.zone===i);return `<div class="heat" style="background:rgba(171,209,97,${a.length?Math.min(.85,.15+a.length/Math.max(known.length,1)):.03})"><div><strong>${a.length}</strong><small>${z}</small><small>${a.filter(s=>s.result==='Tor').length} Tore</small></div></div>`}).join('')}</div><p class="muted" style="margin-top:12px">Aus Sicht des Werfers · ${shots.length-known.length} Würfe ohne Torsegment.</p></div><div class="card"><h2>Ergebnisse</h2><div class="result-summary">${legacyResults.filter(r=>results.includes(r)||shots.some(s=>s.result===r)).map(r=>{const count=shots.filter(s=>s.result===r).length;return `<div><span>${r}</span><b>${count}</b><div class="result-track"><div style="width:${shots.length?count/shots.length*100:0}%"></div></div></div>`}).join('')}</div></div></div>${eventsTable(events)}${keepersTable()}`;
};
function eventsTable(events){const rows=eventSummary(events),totals=rows.reduce((a,r)=>({losses:a.losses+r.losses,errors:a.errors+r.errors,total:a.total+r.total}),{losses:0,errors:0,total:0});return `<div class="card"><h2>Ereignisse ohne Wurf</h2><p class="muted" style="margin:10px 0">Summen je Spieler in der aktuellen Auswahl. Diese Ereignisse zählen nicht als Würfe.</p><div class="tablewrap"><table id="event-summary"><thead><tr><th>Mannschaft</th><th>Spieler</th><th>Ballverlust</th><th>Technischer Fehler</th><th>Summe</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${esc(teamName(p.team))}</td><td>#${esc(p.player)} ${esc(playerName(p.team,p.player))}${playerFlags(team(p.team)?.players.find(x=>x.number===p.player))}</td><td>${p.losses}</td><td>${p.errors}</td><td><b>${p.total}</b></td></tr>`).join('')||'<tr><td colspan="5">Keine Spieler für diese Auswahl.</td></tr>'}</tbody><tfoot><tr><th colspan="2">Gesamt · alle Spieler dieser Auswahl</th><td>${totals.losses}</td><td>${totals.errors}</td><td>${totals.total}</td></tr></tfoot></table></div></div>`}
function keeperRows(){
 const shots=keeperShots().filter(s=>s.keeper&&!['?','empty'].includes(s.keeper)),keys=new Map();
 for(const t of db.teams.filter(t=>matchesTeam(t.id)&&selectedGames().some(g=>[g.home,g.away].includes(t.id))))for(const p of t.players.filter(p=>p.isKeeper))keys.set(JSON.stringify([t.id,p.number]),{team:t.id,number:p.number,name:p.name});
 for(const s of shots)keys.set(JSON.stringify([s.keeperTeam,s.keeper]),{team:s.keeperTeam,number:s.keeper,name:s.keeperName||playerName(s.keeperTeam,s.keeper)});
 return [...keys.values()].map(k=>{const a=shots.filter(s=>s.keeperTeam===k.team&&s.keeper===k.number);return {...k,saved:a.filter(s=>s.result==='Gehalten').length,goals:a.filter(s=>s.result==='Tor').length}}).sort((a,b)=>teamName(a.team).localeCompare(teamName(b.team),'de')||Number(a.number)-Number(b.number));
}
function keepersTable(){const rows=keeperRows(),unknown=keeperShots().filter(s=>!s.keeper||s.keeper==='?').length,empty=keeperShots().filter(s=>s.keeper==='empty').length;return `<div class="card"><h2>Torhüter der ausgewählten Mannschaften</h2><p class="muted" style="margin:10px 0">Gezählt werden Würfe der Gegner auf diese Torhüter. Fangquote = gehalten / (gehalten + Gegentore).</p><div class="tablewrap"><table id="keeper-summary"><thead><tr><th>Mannschaft</th><th>Torhüter</th><th>Gehalten</th><th>Gegentore</th><th>Fangquote</th></tr></thead><tbody>${rows.map(k=>`<tr><td>${esc(teamName(k.team))}</td><td>#${esc(k.number)} ${esc(k.name)}</td><td>${k.saved}</td><td>${k.goals}</td><td>${k.saved+k.goals?Math.round(k.saved/(k.saved+k.goals)*100)+' %':'–'}</td></tr>`).join('')||'<tr><td colspan="5">Keine bekannten Torhüter in dieser Auswahl.</td></tr>'}</tbody></table></div>${unknown||empty?`<p class="muted" style="margin-top:12px">Zusätzlich: ${unknown} Würfe mit unbekanntem Torhüter · ${empty} auf das leere Tor.</p>`:''}</div>`}
function analysisFilterDialog(kind){
 const items=kind==='teams'?db.teams:db.games,selected=filter[kind],title=kind==='teams'?'Mannschaften auswählen':'Spiele auswählen',allLabel=kind==='teams'?'Alle Mannschaften':'Alle Spiele';
 modal(`<form id="analysis-filter-form"><h2>${title}</h2><p class="muted" style="margin:10px 0">Eine, mehrere oder alle auswählen.</p><label class="check-choice all-choice"><input type="checkbox" id="analysis-select-all" ${!selected.length?'checked':''}>${allLabel}</label><div class="analysis-choice-list">${items.map(item=>`<label class="check-choice"><input type="checkbox" data-filter-choice value="${esc(item.id)}" ${!selected.length||selected.includes(item.id)?'checked':''}><span>${kind==='teams'?esc(item.name):`${esc(item.date)} · ${esc(teamName(item.home))} – ${esc(teamName(item.away))}`}</span></label>`).join('')||'<p class="muted">Noch keine Einträge vorhanden.</p>'}</div><div class="dialog-actions"><button type="button" data-close>Abbrechen</button><button class="primary">Übernehmen</button></div></form>`);
 const checks=[...document.querySelectorAll('[data-filter-choice]')],all=$('#analysis-select-all');all.onchange=()=>checks.forEach(c=>c.checked=all.checked);checks.forEach(c=>c.onchange=()=>all.checked=checks.every(c=>c.checked));
 $('#analysis-filter-form').onsubmit=e=>{e.preventDefault();const ids=checks.filter(c=>c.checked).map(c=>c.value);if(items.length&&!ids.length){toast('Bitte mindestens einen Eintrag oder alle auswählen.');return}filter[kind]=ids.length===items.length?[]:ids;$('#dialog').close();render()};
}
function routeColor(n,max){const ratio=max>1?(n-1)/(max-1):0;return `hsl(${Math.round(42-ratio*36)} 85% ${Math.round(46-ratio*5)}%)`}
function heatmapSvg(shots){
 const routes=routesFor(shots),max=Math.max(1,...routes.map(r=>r.count)),fromCount=origin=>routes.filter(r=>r.origin===origin).reduce((n,r)=>n+r.count,0),zoneCount=z=>routes.filter(r=>r.zone===z).reduce((n,r)=>n+r.count,0);
 const goalPoint=z=>({x:536+(z%3+.5)*(464/3),y:25+(Math.floor(z/3)+.5)*(269/3)});
 return `<svg class="player-heatmap" viewBox="0 0 1536 1024" role="img" aria-label="Verbindungen vom Feldsegment zum Torsegment; dickere und rötlichere Linien bedeuten häufigere Würfe"><image href="/handball-court.svg" width="1536" height="1024"/>${fieldSegments.map(([origin,points])=>`<g class="heat-field" style="--heat-opacity:${fromCount(origin)?Math.min(.5,.08+fromCount(origin)/Math.max(shots.length,1)*.45):0}">${origin==='Kreis Mitte'?'<path d="M622 445H914L983 604H553Z M710 470V532H826V470Z" fill-rule="evenodd"/>':`<polygon points="${points}"/>`}</g>`).join('')}${zones.map((z,i)=>`<rect x="${536+i%3*464/3}" y="${25+Math.floor(i/3)*269/3}" width="${464/3}" height="${269/3}" fill="${zoneCount(i)?'#f7c74b':'#143c3a'}" fill-opacity="${zoneCount(i)?0.25+0.55*zoneCount(i)/Math.max(shots.length,1):0.15}" stroke="#fff" stroke-width="5"/>`).join('')}${routes.slice().reverse().map(r=>{const [x,y]=fieldSegments.find(s=>s[0]===r.origin)[2].split(',').map(Number),t=goalPoint(r.zone),d=`M${x} ${y} L${t.x} ${t.y}`,width=4+Math.sqrt(r.count)*5;return `<g class="heat-route"><title>${esc(r.origin)} → ${zones[r.zone]}: ${r.count} Würfe, ${r.goals} Tore</title><path d="${d}" stroke="#fff" stroke-width="${width+6}" stroke-opacity=".7"/><path d="${d}" stroke="${routeColor(r.count,max)}" stroke-width="${width}" stroke-opacity=".86"/><circle cx="${x}" cy="${y}" r="9" fill="${routeColor(r.count,max)}"/></g>`}).join('')}${fieldSegments.map(([origin,,center,label])=>{const [x,y]=center.split(',').map(Number);return `<text class="heat-label" x="${x}" y="${y+44}" text-anchor="middle">${label} · ${fromCount(origin)}</text>`}).join('')}${zones.map((z,i)=>{const t=goalPoint(i);return `<circle cx="${t.x}" cy="${t.y}" r="29" fill="#fff" fill-opacity=".93"/><text class="heat-goal-label" x="${t.x}" y="${t.y+11}" text-anchor="middle">${zoneCount(i)}</text>`}).join('')}</svg>`;
}
function playerHeatmap(tid,number){
 const shots=filtered().filter(s=>s.team===tid&&s.player===number),routes=routesFor(shots),mapped=routes.reduce((n,r)=>n+r.count,0),goals=shots.filter(s=>s.result==='Tor').length;
 modal(`<div class="card-head"><div><div class="eyebrow">${esc(teamName(tid))}</div><h2>Wurfbild · #${esc(number)} ${esc(playerName(tid,number))}${playerFlags(team(tid)?.players.find(p=>p.number===number))}</h2></div><button data-close>Schließen</button></div><p class="muted">${shots.length} Würfe · ${goals} Tore · Auswahl: ${selectedGames().length} ${selectedGames().length===1?'Spiel':'Spiele'}</p><div class="heatmap-frame">${heatmapSvg(shots)}</div><div class="heatmap-legend"><span><i></i> Seltener</span><span><i></i> Häufiger</span><span>Dickere Linie = mehr Würfe auf derselben Verbindung</span></div><p class="muted heatmap-note">Alle Wurfergebnisse · Links und rechts aus Sicht des Werfers. Jede Linie verbindet ein Feld- mit einem Torsegment. Gleiche Verbindungen sind zusammengefasst; die Zahlen im Tor zählen alle zugeordneten Würfe.</p>${mapped<shots.length?`<div class="notice">${shots.length-mapped} ältere Würfe ohne vollständiges Feld- und Torsegment sind in der Statistik enthalten, können hier aber nicht als Verbindung dargestellt werden.</div>`:''}<div class="tablewrap"><table><thead><tr><th>Feldsegment</th><th>Torsegment</th><th>Würfe</th><th>Tore</th></tr></thead><tbody>${routes.map(r=>`<tr><td>${r.origin}</td><td>${zones[r.zone]}</td><td><b>${r.count}</b></td><td>${r.goals}</td></tr>`).join('')||'<tr><td colspan="4">Noch keine vollständigen Würfe in dieser Auswahl.</td></tr>'}</tbody></table></div>`);
 $('#dialog').classList.add('heatmap-dialog');$('#dialog').addEventListener('close',()=>$('#dialog').classList.remove('heatmap-dialog'),{once:true});
}
const bindBeforeAnalysis=bind;
bind=function(){bindBeforeAnalysis();document.querySelectorAll('[data-analysis-filter]').forEach(b=>b.onclick=()=>analysisFilterDialog(b.dataset.analysisFilter));document.querySelectorAll('[data-heat-team]').forEach(row=>{const show=()=>playerHeatmap(row.dataset.heatTeam,row.dataset.heatPlayer);row.onclick=show;row.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();show()}}})};
render();
